  "verifyEmail.newCodeOnlyNote": "புதிய குறியீடு முற்றிலும் புதிய கணக்கிற்கு மட்டுமே அனுப்பப்படும். இந்த மின்னஞ்சலுடன் நீங்கள் முன்பே கணக்கை உருவாக்கியிருந்தால், அப்போது நீங்கள் அமைத்த கடவுச்சொல்லுடன் உள்நுழையவும் — புதிய குறியீடு வராது.",
