  "reset.invalidSubtitle": "இந்தக் கடவுச்சொல் மீட்டமைப்பு இணைப்பு காணவில்லை அல்லது தவறானது",
  "reset.requestNewLink": "புதிய இணைப்பைக் கோரவும்",
  "reset.invalidBody": "நீங்கள் பயன்படுத்திய இணைப்பு முழுமையற்றதாகத் தெரிகிறது. புதிய கடவுச்சொல் மீட்டமைப்பு மின்னஞ்சலைக் கோரவும்.",
  "reset.title": "புதிய கடவுச்சொல்",
  "reset.subtitle": "கீழே உங்கள் புதிய கடவுச்சொல்லை உள்ளிடவும்",
  "reset.newPasswordLabel": "புதிய கடவுச்சொல்",
