  "reset.resetting": "மீட்டமைக்கப்படுகிறது...",
  "reset.failed": "கடவுச்சொல்லை மீட்டமைக்க முடியவில்லை",
  "reset.codePrompt": "உங்கள் மீட்டமைப்பு மின்னஞ்சலில் உள்ள 6 இலக்கக் குறியீடு உங்களிடம் உள்ளதா? அதை இங்கே உள்ளிடவும்:",
