  "plans.policyEffectiveSplit": "சேவை விதிமுறைகள் {termsDate} முதல் நடைமுறையில் உள்ளன, மேலும் சந்தா, ரத்து & பணத்தைத் திரும்பப் பெறும் கொள்கை {policyDate} முதல் நடைமுறையில் உள்ளது.",
