  "import.eyebrow": "தரவு",
  "import.title": "இறக்குமதி மையம்",
  "import.subtitleStart": "மூன்று தனித்தனி விரிதாள் செயல்பாடுகள், எனவே விலைத் திருத்தம் ஒருபோதும் இருப்புப் பெறுதலாக வர முடியாது. அனைத்தும் இதில் மட்டுமே வந்து சேரும்",
  "import.subtitleRest": ", மேலும் உலர் சோதனை தேர்ச்சி பெறும் வரை எதுவும் எழுதப்படாது.",
  "import.createBusinessFirst": "முதலில் ஒரு வணிகத்தை உருவாக்கவும் — இறக்குமதி செய்யப்பட்ட தயாரிப்புகள் ஒரு வணிகத்திற்கு உரியவை.",
  "import.createBusinessFirstShort": "முதலில் ஒரு வணிகத்தை உருவாக்கவும்.",
  "import.whatEachDoes": "ஒவ்வொரு செயல்பாடும் என்ன செய்கிறது",
  "import.createTitle": "புதிய தயாரிப்புகளை உருவாக்கவும்",
  "import.createDesc": "இன்னும் பட்டியலில் இல்லாத வரிசைகளைச் சேர்க்கிறது. ஏற்கனவே பயன்பாட்டில் உள்ள நகல் SKU-கள் மற்றும் பார்கோடுகள் தவிர்க்கப்படுகின்றன, மேலும் தொடக்க இருப்பு நீங்கள் தேர்ந்தெடுக்கும் இடத்தில் பெறுதலாக வந்து சேரலாம்.",
  "import.updateTitle": "ஏற்கனவே உள்ள தயாரிப்புகளைப் புதுப்பிக்கவும்",
  "import.updateDesc": "ஒவ்வொரு வரிசையையும் SKU அல்லது பதிவு ID மூலம் பொருத்தி, பழைய மதிப்பை முன்மொழியப்பட்ட புதிய மதிப்பிற்கு அருகில் காட்டுகிறது. வெற்றுக் கலங்களை அழிக்க நீங்கள் கேட்காவிட்டால் வெற்றுக் கலங்கள் சேமிக்கப்பட்ட மதிப்பை அப்படியே விட்டுவிடும், மேலும் அளவுகள் ஒருபோதும் தொடப்படாது.",
  "import.receiveModeTitle": "இருப்பைப் பெறவும்",
  "import.receiveModeDesc": "வரும் அளவுகளை ஒரு இடத்தில் சேர்த்து, ஒவ்வொரு வரிக்கும் இயக்கப் பதிவேட்டில் ஒரு பெறுதலை எழுதுகிறது. ஒவ்வொரு தொகுப்பும் குறிக்கப்பட்டுள்ளது, எனவே அதே தாளை இரண்டு முறை பெற முடியாது.",
  "import.excelNote": "Excel பணிப்புத்தகங்கள் (.xlsx) நேரடியாகப் படிக்கப்படுகின்றன — பணித்தாளைத் தேர்ந்தெடுக்கவும், நெடுவரிசைகள் உங்களுக்காகப் பொருத்தப்படும். குறியீடுகள் முழுமையாக இருக்கும்: உரையாகச் சேமிக்கப்பட்ட UPC அதன் இலக்கங்களையும் முன்னணி பூஜ்ஜியங்களையும் வைத்திருக்கும். இறக்குமதி செய்ய முடியாத வரிசைகள் காரணத்துடன் பட்டியலிடப்பட்டுள்ளன",
  "import.excelNoteDownload": " மேலும் கோப்பாகப் பதிவிறக்கலாம்.",
  "import.excelNoteFix": ", எனவே அவற்றைச் சரிசெய்து மீண்டும் முயற்சிக்கலாம்.",
  "import.matchColumns": "நெடுவரிசைகளைப் பொருத்தவும்",
  "import.columnFallback": "நெடுவரிசை {column}",
  "import.ignoreColumn": "இந்த நெடுவரிசையைப் புறக்கணிக்கவும்",
  "import.mapNameRequired": "ஒரு நெடுவரிசையை தயாரிப்பு பெயருடன் பொருத்தவும் — இறக்குமதி செய்யப்படும் ஒவ்வொரு வரிசைக்கும் ஒரு பெயர் தேவை.",
  "import.receiveMissingMessage": "ஒரு நெடுவரிசையை SKU அல்லது பதிவு ID உடனும், ஒன்றைப் பெறப்பட்ட அளவுடனும் பொருத்தவும்.",
