  "import.updateIntro": "ஒவ்வொரு வரிசைக்கும் ஒரு SKU அல்லது பதிவு ID தேவை, அதனால் அது உரிய தயாரிப்புடன் பொருத்தப்படலாம். ஒவ்வொரு பழைய மதிப்பையும் அதன் முன்மொழியப்பட்ட புதிய மதிப்பிற்கு அருகில் காண்பீர்கள், பின்னர் உலர் சோதனையை இயக்கி, எதுவும் சேமிக்கப்படுவதற்கு முன் உறுதிப்படுத்துவீர்கள். வெற்றுக் கலங்கள் ஏற்கனவே உள்ள மதிப்பை அப்படியே விட்டுவிடும்.",
