  "reports.title": "அறிக்கைகள்",
  "reports.subtitle": "எதைப் பார்க்க வேண்டும், எப்படித் தொகுக்க வேண்டும், எந்தக் காலகட்டத்தில் என்பதைத் தேர்ந்தெடுக்கவும். ஒவ்வொரு எண்ணும் உங்கள் சொந்த இருப்பு மற்றும் இயக்கப் பதிவுகளிலிருந்து கணக்கிடப்படுகிறது, மேலும் அட்டவணையைக் கோப்பாகப் பதிவிறக்கலாம்.",
