  "reports.nothingToRank": "இன்னும் தரவரிசைப்படுத்த எதுவும் இல்லை",
  "reports.missingMoney": "இந்தக் காட்சியில் {units} அலகுக்கு {label} பதிவு செய்யப்படவில்லை. விடுபட்ட பணம் ஒருபோதும் பூஜ்ஜியமாகக் கருதப்படாது — அவை இலவசமாகக் கணக்கிடப்படுவதற்குப் பதிலாக எண்களிலிருந்து விடப்படுகின்றன. அந்தத் தயாரிப்புகளில் எண்ணைச் சேர்க்கவும், மொத்தங்கள் நிரம்பும்.",
  "reports.movementsCapped": "புதிய {cap} பதிவேட்டு உள்ளீடுகள் மட்டுமே படிக்கப்பட்டன, எனவே இவற்றை விடப் பழைய இயக்கங்கள் மொத்தங்களில் இல்லை. ஒரு காலகட்டத்திற்கான சரியான எண்களைக் காண காலகட்டத்தைக் குறுக்கவும்.",
  "reports.footnote": "விற்பனை ஒவ்வொரு தயாரிப்பின் தற்போதைய சில்லறை விலையையும், பெறுதல்கள் இருப்பு வந்தபோது பதிவு செய்யப்பட்ட செலவையும், இழப்புகள் தற்போதைய அலகு செலவையும் பயன்படுத்துகின்றன. விடுபட்ட பணம் ஒருபோதும் பூஜ்ஜியமாகக் கருதப்படாது — அது தெரியும் வரை ஒரு எண்ணை வெற்றாக விடவும். அறிக்கை ஒரு காட்சி, ஆவணம் அல்ல: நீங்கள் ஒன்றை இயக்கும்போது உங்கள் பதிவுகளில் எதுவும் எழுதப்படாது.",
  "reports.createBusinessFirst": "முதலில் ஒரு வணிகத்தை உருவாக்கவும் — அறிக்கைகள் வணிக வாரியாகக் கணக்கிடப்படுகின்றன.",
