  "valuation.noRetailPrice": "சில்லறை விலை இல்லை",
  "valuation.footnote": "செலவு மதிப்பு ஒவ்வொரு தயாரிப்பின் தற்போதைய அலகு செலவைப் பயன்படுத்துகிறது, எனவே புதிய விலையில் பெறுவது முழு அலமாரியையும் மீண்டும் மதிப்பிடும். வைக்கப்பட்ட அலகுகள் இன்னும் இங்கே கணக்கிடப்படுகின்றன — அவை கையில் உள்ளன, ஒரு ஆணைக்கு வாக்குறுதி அளிக்கப்பட்டுள்ளன. விடுபட்ட பணம் ஒருபோதும் பூஜ்ஜியமாகக் கருதப்படாது; எண் தெரியும் வரை ஒரு புலத்தை வெற்றாக விடவும்.",
  "print.eyebrow": "அச்சு மையம்",
  "print.title": "லேபிள்கள் மற்றும் தாள்கள்",
  "print.subtitleFull": "ஸ்கேன் செய்யக்கூடிய லேபிள்கள், இருப்புத் தாள்கள், எடுப்புப் பட்டியல்கள், கொள்வனவு ஆணைகள், வாடிக்கையாளர் விலைப்பட்டியல்கள், ரசீதுகள் மற்றும் திருப்ப ஆவணங்கள்.",
