  "print.directDesc": "லேபிள்கள் இரண்டு திட்டங்களிலும் அச்சிடப்படும், இவை நேரடியாக அச்சுப்பொறிக்குச் செல்லும் — இந்தப் பக்கம் ஏற்றப்பட்டவுடன் இணையம் தேவையில்லை.",
