  "plan.gate.body": "உங்கள் பணியிடம் {plan} திட்டத்தில் உள்ளது. Business ஆனது {feature}, வரம்பற்ற தயாரிப்புகள் மற்றும் பணியாளர்கள், விநியோகஸ்தர்கள், கொள்வனவு, ஏற்றுமதிகள் மற்றும் தொகுப்புகளைச் சேர்க்கிறது. உங்களிடம் தற்போது உள்ள அனைத்தும் தொடர்ந்து செயல்படும்.",
