  "settings.appearance.automatic": "தானியங்கு",
  "settings.appearance.automaticDesc": "இந்தச் சாதனத்தின் தோற்ற அமைப்பைப் பின்பற்றவும்.",
  "settings.appearance.dark": "அடர்",
  "settings.appearance.darkDesc": "கிட்டத்தட்ட கருப்பு பின்னணி மற்றும் வெதுவெதுப்பான பழுப்பு தலைப்பு.",
  "settings.appearance.description": "இந்தச் சாதனத்தில் Luminous StockHaven இன் தோற்றத்தைத் தேர்ந்தெடுக்கவும். மாற்றங்கள் பயன்பாடு முழுவதும் உடனடியாகப் பொருந்தும்.",
