  "settings.appearance.light": "வெளிர்",
  "settings.appearance.lightDesc": "வெள்ளை பின்னணி மற்றும் வெதுவெதுப்பான பழுப்பு தலைப்பு.",
  "settings.appearance.remembered": "உங்கள் தேர்வு இந்த உலாவி அல்லது பயன்பாட்டில் நினைவில் வைக்கப்படும். அது வணிகப் பதிவுகளை மாற்றாது அல்லது மேலே உள்ள படிவத்தைச் சேமிக்க வேண்டியதில்லை.",
  "settings.appearance.title": "தோற்றம்",
  "settings.billing.checking": "Stripe சந்தா நிலையைச் சரிபார்க்கிறது…",
  "settings.billing.readOnlyNote": "இந்தப் படிக்க-மட்டும் முடிவு, கட்டணம் செலுத்தப்பட்ட தேதியை உறுதிப்படுத்தாது அல்லது ரத்து கோரிக்கையைச் சமர்ப்பிக்காது.",
  "settings.billing.refresh": "நிலையைப் புதுப்பிக்கவும்",
