  "settings.billing.unavailableDetail": "இந்த வணிகத்திற்கான தற்போதைய Stripe சந்தாவை எங்களால் சரிபார்க்க முடியவில்லை. உங்கள் சந்தா ரத்து செய்யப்பட்டது, செயலற்றது, அல்லது எதிர்காலக் கட்டணங்கள் இல்லாதது என்று இதற்கு அர்த்தமில்லை.",
