  "settings.separateDecisions": "சந்தா ரத்து மற்றும் கணக்கு நீக்கம் தனித்தனி முடிவுகள். இந்த விதிமுறைகளைப் பார்ப்பதால் எந்தச் சந்தாவும் ரத்து செய்யப்படாது அல்லது கணக்கும் நீக்கப்படாது.",
  "settings.software.application": "பயன்பாடு",
  "settings.software.description": "Luminous StockHaven என்பது பயன்பாடு ஆகும். இந்தப் பக்கத்தில் வேறு இடங்களில் உள்ள உங்கள் வணிக விவரங்கள் உங்களுடையவை.",
  "settings.software.fixedNote": "இந்த மதிப்புகள் நிலையானவை மற்றும் ஒவ்வொரு வணிகத்திற்கும் ஒரே மாதிரியாகத் தோன்றும். உங்கள் வணிகத்தின் பெயரை மாற்றுவது அல்லது அதன் லோகோவை மாற்றுவது பயன்பாட்டின் பெயரை ஒருபோதும் மாற்றாது.",
