  "settings.switcher.nameError": "இந்த வணிகத்திற்கு ஒரு பெயரைக் கொடுக்கவும்.",
  "settings.switcher.nameLabel": "வணிகப் பெயர்",
  "settings.switcher.namePlaceholder": "Harbor & Pine Books",
  "settings.switcher.new": "புதியது",
  "settings.switcher.newDescription": "ஒவ்வொரு வணிகமும் தனது சொந்த தயாரிப்புகள், இடங்கள், விநியோகஸ்தர்கள் மற்றும் கொள்வனவு ஆர்டர்களை வைத்திருக்கும். அவற்றுக்கிடையே எதுவும் பகிரப்படாது.",
