  "policies.translationNotice": "இந்த மொழிபெயர்ப்பு உங்கள் மொழியில் அதைப் படிக்க முடியும் என்பதற்காக வழங்கப்படுகிறது. இந்த மொழிபெயர்ப்புக்கும் ஆங்கிலப் பதிப்புக்கும் இடையே எப்போதாவது கருத்து வேறுபாடு இருந்தால், ஆங்கிலப் பதிப்பே அதிகாரப்பூர்வமானது.",
