  "payroll.dd.formTitle": "நேரடி வைப்பு அங்கீகாரப் படிவம்",
  "payroll.dd.help": "ஒவ்வொரு குழு உறுப்பினரின் வங்கி விவரங்களையும் பாதுகாப்பாகச் சேகரிக்கவும். சமர்ப்பிக்கப்பட்ட விவரங்கள் உரிமையாளருக்கு மட்டுமே செல்லும் — வேறு யாரும் அவற்றைப் பார்க்க முடியாது.",
  "payroll.dd.invite": "கோரிக்கையை அனுப்பவும்",
