  "payroll.dd.printForm": "காகிதப் படிவத்தை அச்சிடவும்",
  "payroll.dd.routing": "Routing எண் (9 இலக்கங்கள்)",
  "payroll.dd.savings": "சேமிப்புக் கணக்கு (Savings)",
  "payroll.dd.steps.body": "1. ACH கட்டணங்களை அனுப்பக்கூடிய ஒரு வணிக வங்கிக் கணக்கு உங்களுக்குத் தேவை. 2. ஒவ்வொரு குழு உறுப்பினரிடமிருந்தும் கையொப்பமிட்ட அங்கீகாரப் படிவத்தைச் சேகரிக்கவும் — ரத்து செய்யப்பட்ட காசோலை எண்களைச் சரிபார்க்க உதவும். 3. சம்பள நாளுக்கு 2-3 வணிக நாட்களுக்கு முன் ஊதியப்பட்டியலை அனுப்பவும், அப்போதுதான் பணம் சரியான நேரத்தில் சென்றடையும். 4. பெரும்பாலான மாநிலங்கள் குழு உறுப்பினரின் எழுத்துப்பூர்வ ஒப்புதலைக் கோருகின்றன. இந்தப் பயன்பாடு படிவங்களைச் சேகரித்து படிகளை வழிநடத்துகிறது — பணத்தை உண்மையில் அனுப்புவது உங்கள் சொந்த வங்கி மூலமே நடக்கும்.",
  "payroll.dd.steps.title": "நேரடி வைப்பு எப்படி வேலை செய்கிறது",
