  "workforce.messages.help": "உங்கள் குழுவுடன் தனிப்பட்ட ஒருவருக்கு ஒருவர் செய்திகள் — வேறு பயன்பாடு தேவையில்லை. ஒரு உரையாடலில் உள்ள இருவர் மட்டுமே அதைப் படிக்க முடியும், மேலும் தங்கள் கடையை மேற்பார்வையிடும் வணிக உரிமையாளரும் படிக்கலாம்.",
