  "training.module.workforce": "பணியாளர் குழு மற்றும் நேரக் கடிகாரம்",
  "training.newForYou": "உங்களுக்கான புதிய பயிற்சி",
  "training.newForYouHelp": "இந்தப் பாடங்கள் உங்கள் பங்கு வளர்ந்ததால், அல்லது யாரோ அவற்றை உங்களுக்கு ஒதுக்கியதால் சேர்க்கப்பட்டன. பயன்பாட்டின் புதிய பகுதிகளை அறிய அவற்றை முடிக்கவும்.",
