  "training.sourceRole": "உங்கள் பங்கு வளர்ந்தபோது சேர்க்கப்பட்டது",
  "training.steps": "படிகள்",
  "training.subtitle": "பயன்பாட்டின் ஒவ்வொரு பகுதியையும், படிப்படியாக, உங்கள் சொந்த வேகத்தில் கற்றுக் கொள்ளவும். உங்கள் பாடங்கள் உங்கள் பங்கிற்குப் பொருந்தும்.",
