  "training.team.deadlineSaved": "காலக்கெடு சேமிக்கப்பட்டது.",
  "training.team.help": "யார் எதை முடித்தார்கள் என்பதைப் பார்க்கவும், பாடங்களை ஒதுக்கவும், காலக்கெடுக்களை அமைக்கவும், பயிற்சி காலாவதியானபோது ஒரு எச்சரிக்கையை அனுப்பவும்.",
