  "rewards.give.detailPlaceholder": "வெகுமதியை உங்கள் சொந்த வார்த்தைகளில் விவரிக்கவும்",
  "rewards.give.help": "வெகுமதிகள் ஒரு குழு உறுப்பினருக்குச் செல்லும். மேலாளர்கள் பணியாளர்களுக்கு வெகுமதி அளிக்கிறார்கள்; உரிமையாளர் குழுவில் உள்ள யாருக்கும் வெகுமதி அளிக்கலாம்.",
  "rewards.give.kind": "வெகுமதியின் வகை",
