  "rewards.give.recipient": "குழு உறுப்பினர்",
  "rewards.give.sent": "வெகுமதி வழங்கப்பட்டது — {name} க்கு அது அவர்களின் வெகுமதிகளிலும் அவர்களின் மணியிலும் உள்ளது.",
  "rewards.give.submit": "வெகுமதியை வழங்கவும்",
