  "rewards.mine.empty": "இன்னும் வெகுமதிகள் இல்லை. உங்கள் மேலாளர் அல்லது உரிமையாளர் உங்களுக்கு ஒன்றைக் கொடுக்கும்போது, அது இங்கே வரும்.",
  "rewards.mine.from": "{name} இடமிருந்து",
