  "rewards.redeem.done": "வெகுமதி பயன்படுத்தப்பட்டதாகக் குறிக்கப்பட்டது.",
  "rewards.redeem.help": "குழு உறுப்பினர் உங்களுக்குக் காட்டும் குறியீட்டைத் தட்டச்சு செய்யவும். ஒவ்வொரு குறியீடும் ஒருமுறை வேலை செய்யும்.",
  "rewards.redeem.placeholder": "வெகுமதிக் குறியீடு",
