  "pos.events.empty": "இன்னும் கல்லாப் பெட்டி விற்பனை இல்லை. இணைக்கப்பட்ட கல்லாப் பெட்டி எதையாவது விற்கும்போது, அது இங்கே தோன்றும்.",
  "pos.events.title": "சமீபத்திய கல்லாப் பெட்டி விற்பனை",
